-- Omacast snippet keyword expansion.
--
-- Loaded from ~/.config/omacast/hyprland.lua (generated by omacast-hotkeys)
-- only when expansion is enabled in Omacast settings. It watches key presses
-- through Hyprland, keeps the last few printable characters in memory (never
-- written anywhere), and when they end with a snippet keyword asks Omacast to
-- replace the keyword with the snippet.
--
-- Keycodes are mapped with a US QWERTY table; other layouts may not match.
-- Event arguments: XKB keycode (evdev + 8), timestamp in ms, state (1 = down).

local cfg = omacast_expansion or {}
local keywords = cfg.keywords or {}
if #keywords == 0 then return end

table.sort(keywords, function(a, b) return #a > #b end)

local exclude = {}
for _, c in ipairs(cfg.exclude or {}) do exclude[string.lower(c)] = true end
local within_words = cfg.within_words == true
local command = cfg.command or "omarchy-shell shell call stefans.omacast expandKeyword"

-- XKB keycodes (evdev + 8) → { plain, shifted }
local map = {
  [10] = { "1", "!" }, [11] = { "2", "@" }, [12] = { "3", "#" }, [13] = { "4", "$" },
  [14] = { "5", "%" }, [15] = { "6", "^" }, [16] = { "7", "&" }, [17] = { "8", "*" },
  [18] = { "9", "(" }, [19] = { "0", ")" }, [20] = { "-", "_" }, [21] = { "=", "+" },
  [24] = { "q", "Q" }, [25] = { "w", "W" }, [26] = { "e", "E" }, [27] = { "r", "R" },
  [28] = { "t", "T" }, [29] = { "y", "Y" }, [30] = { "u", "U" }, [31] = { "i", "I" },
  [32] = { "o", "O" }, [33] = { "p", "P" }, [34] = { "[", "{" }, [35] = { "]", "}" },
  [38] = { "a", "A" }, [39] = { "s", "S" }, [40] = { "d", "D" }, [41] = { "f", "F" },
  [42] = { "g", "G" }, [43] = { "h", "H" }, [44] = { "j", "J" }, [45] = { "k", "K" },
  [46] = { "l", "L" }, [47] = { ";", ":" }, [48] = { "'", "\"" }, [49] = { "`", "~" },
  [51] = { "\\", "|" }, [52] = { "z", "Z" }, [53] = { "x", "X" }, [54] = { "c", "C" },
  [55] = { "v", "V" }, [56] = { "b", "B" }, [57] = { "n", "N" }, [58] = { "m", "M" },
  [59] = { ",", "<" }, [60] = { ".", ">" }, [61] = { "/", "?" }, [65] = { " ", " " },
}
local BACKSPACE = 22
local MODIFIERS = { [37] = true, [105] = true, [50] = true, [62] = true, [64] = true,
  [108] = true, [133] = true, [134] = true, [66] = true }

local buffer = ""
local busy = false

-- Optional diagnostics: omacast_expansion.debug_until = os.time() + 60 logs key
-- numbers and the matched buffer to /tmp/omacast-expand-debug.log until then.
local function debug(line)
  if not cfg.debug_until or os.time() > cfg.debug_until then return end
  local f = io.open("/tmp/omacast-expand-debug.log", "a")
  if f then f:write(line .. "\n"); f:close() end
end
omacast_expansion_loaded = true

local function down(name)
  local ok, value = pcall(hl.is_key_down, name)
  return ok and value == true
end

local function excluded()
  local ok, win = pcall(hl.get_last_window)
  if not ok or not win then return false end
  local class = string.lower(tostring(win.class or ""))
  for pattern in pairs(exclude) do
    if class:find(pattern, 1, true) then return true end
  end
  return false
end

local function boundary_ok(kw)
  if within_words then return true end
  local before = buffer:sub(1, #buffer - #kw)
  if before == "" then return true end
  return not before:sub(-1):match("[%w]")
end

hl.on("window.active", function() buffer = "" end)

-- Input methods such as fcitx5 re-send each key through a virtual keyboard,
-- so the same press can arrive twice with the same timestamp. Count it once.
local last_key, last_time, last_state

hl.on("input.keyboard.key", function(keycode, time, state)
  if keycode == last_key and time == last_time and state == last_state then return end
  last_key, last_time, last_state = keycode, time, state
  debug(string.format("key=%s time=%s state=%s busy=%s", tostring(keycode), tostring(time), tostring(state), tostring(busy)))
  if busy or state ~= 1 then return end
  keycode = tonumber(keycode)
  if MODIFIERS[keycode] then return end

  if keycode == BACKSPACE then
    buffer = buffer:sub(1, -2)
    return
  end

  local entry = map[keycode]
  if not entry or down("Control_L") or down("Control_R") or down("Alt_L") or down("Super_L") or down("Super_R") then
    buffer = ""
    return
  end

  local shifted = down("Shift_L") or down("Shift_R")
  buffer = (buffer .. entry[shifted and 2 or 1]):sub(-64)
  debug("buffer=" .. buffer)

  for _, kw in ipairs(keywords) do
    if #buffer >= #kw and buffer:sub(-#kw) == kw and boundary_ok(kw) then
      buffer = ""
      debug("matched " .. kw .. " excluded=" .. tostring(excluded()))
      if excluded() then return end
      busy = true
      hl.exec_cmd(command .. " '" .. kw:gsub("'", "'\\''") .. "' >/dev/null 2>&1")
      hl.timer(function() busy = false end, { timeout = 1500, type = "oneshot" })
      return
    end
  end
end)
